def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sr, sc = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 3)
    # The nested frames are centered one cell to the right of the seed.
    cr, cc = sr, sc + 1
    for radius in (2, 4, 6, 8, 10, 12):
        top, bottom = cr - radius, cr + radius
        left, right = cc - radius, cc + radius
        for c in range(left, right + 1):
            for r in (top, bottom):
                if 0 <= r < h and 0 <= c < w and out[r][c] != 2:
                    out[r][c] = 3
        for r in range(top, bottom + 1):
            for c in (left, right):
                if 0 <= r < h and 0 <= c < w and out[r][c] != 2:
                    out[r][c] = 3
    return out
